var gsplatCorner_default = (
  /* wgsl */
  `
uniform viewport_size: vec4f;             // viewport width, height, 1/width, 1/height
uniform minPixelSize: f32;
#if GSPLAT_AA
    uniform antiAliasFilterSize: f32;     // GSplatParams#antiAliasFilterSize, in pixels squared
#endif

// Rotation and scale source data are f16; covariance must be f32 to avoid scale^2 overflow
fn computeCovariance(rotation: half4, scale: half3, covA_ptr: ptr<function, vec3f>, covB_ptr: ptr<function, vec3f>) {
    let rot: half3x3 = quatToMat3(rotation);
    let s: vec3f = vec3f(scale);

    // M = S * R (promote to f32 to avoid overflow in dot products)
    let M: mat3x3f = transpose(mat3x3f(
        s.x * vec3f(rot[0]),
        s.y * vec3f(rot[1]),
        s.z * vec3f(rot[2])
    ));

    *covA_ptr = vec3f(dot(M[0], M[0]), dot(M[0], M[1]), dot(M[0], M[2]));
    *covB_ptr = vec3f(dot(M[1], M[1]), dot(M[1], M[2]), dot(M[2], M[2]));
}

// calculate the clip-space offset from the center for this gaussian
fn initCornerCov(source: ptr<function, SplatSource>, center: ptr<function, SplatCenter>, corner: ptr<function, SplatCorner>, covA: vec3f, covB: vec3f) -> bool {

    let Vrk = mat3x3f(
        vec3f(covA.x, covA.y, covA.z),
        vec3f(covA.y, covB.x, covB.y),
        vec3f(covA.z, covB.y, covB.z)
    );

    let v = center.view.xyz;

    #ifdef GSPLAT_FISHEYE

        let focal = uniform.viewport_size.x * center.projMat00;

        // Generalized fisheye Jacobian for g(\u03B8) = k\xB7tan(\u03B8/k)
        // fisheyeSinTK, fisheyeCosTK, fisheyeRxy are shared from center shader
        let r_sq = max(center.fisheyeRxy * center.fisheyeRxy, 1e-8);
        let d2 = dot(v, v);
        let neg_z = -v.z;
        let g_prime = 1.0 / (center.fisheyeCosTK * center.fisheyeCosTK);
        let g_theta = uniform.fisheye_k * center.fisheyeSinTK / center.fisheyeCosTK;
        let sv = select(select(0.0, 1.0 / neg_z, neg_z > 0.0), g_theta / center.fisheyeRxy, center.fisheyeRxy > 1e-4);
        let K = select(0.0, (g_prime * neg_z / d2 - sv) / r_sq, center.fisheyeRxy > 1e-4);

        var J = mat3x3f(
            vec3f(focal * (sv + K * v.x * v.x),  focal * K * v.x * v.y,       focal * g_prime * v.x / d2),
            vec3f(focal * K * v.x * v.y,         focal * (sv + K * v.y * v.y), focal * g_prime * v.y / d2),
            vec3f(0.0, 0.0, 0.0)
        );

        // mirror the footprint along with the center when the target flips Y
        J[1] = J[1] * sign(center.projMat11);

    #else

        // Standard perspective Jacobian. The focal length in pixels is taken per axis: the two
        // differ when the viewport's pixel aspect doesn't match the projection's (e.g. a
        // full-frame projection drawn into half the width of a side-by-side stereo target). The
        // signs are kept: the footprint is added to the center in clip space, so it must be
        // mirrored along with it when the projection flips an axis (e.g. a flipY render target).
        let focal = uniform.viewport_size.xy * vec2f(center.projMat00, center.projMat11);
        let vp = select(center.view.xyz, vec3f(0.0, 0.0, 1.0), uniform.camera_params.w == 1.0);
        let J1 = focal / vp.z;
        let J2 = -J1 / vp.z * vp.xy;
        let J = mat3x3f(
            vec3f(J1.x, 0.0, J2.x),
            vec3f(0.0, J1.y, J2.y),
            vec3f(0.0, 0.0, 0.0)
        );

    #endif

    // Firefox on Windows (D3D12) returns a transposed matrix when a struct member is indexed
    // through a pointer, so load the whole matrix into a local first. Remove the local once the
    // fix has shipped: https://bugzilla.mozilla.org/show_bug.cgi?id=2059727
    let modelView = center.modelView;
    let W = transpose(mat3x3f(modelView[0].xyz, modelView[1].xyz, modelView[2].xyz));
    let T = W * J;
    let cov = transpose(T) * Vrk * T;

    // early-out gaussians smaller than minPixelSize, before paying for the eigen-decomposition (the vmin
    // cap below is left out: it only matters on a viewport under minPixelSize / 2 pixels)
    if (gsplatFootprintSmallerThan(cov[0][0] + GSPLAT_CULL_LOWPASS, cov[0][1], cov[1][1] + GSPLAT_CULL_LOWPASS, uniform.minPixelSize)) {
        return false;
    }

    // screen-space filter: the classic dilation, or for compensated splats the filter they were
    // trained with (antiAliasFilterSize is in pixels squared, cov in half pixel units)
    var lowpass = GSPLAT_LOWPASS;
    #if GSPLAT_AA
        var compensated = true;
        #ifdef GSPLAT_AA_MIXED
            // the scene mixes splats trained with and without anti-aliasing; only the ones flagged
            // in the work buffer are compensated
            compensated = getAntiAlias();
        #endif
        if (compensated) {
            lowpass = 4.0 * uniform.antiAliasFilterSize;
        }

        // calculate AA factor
        let detOrig = cov[0][0] * cov[1][1] - cov[0][1] * cov[1][0];
        let detBlur = (cov[0][0] + lowpass) * (cov[1][1] + lowpass) - cov[0][1] * cov[1][0];
        corner.aaFactor = select(half(1.0), half(sqrt(max(detOrig / detBlur, 0.0))), compensated);
    #endif

    let diagonal1 = cov[0][0] + lowpass;
    let offDiagonal = cov[0][1];
    let diagonal2 = cov[1][1] + lowpass;

    let mid = 0.5 * (diagonal1 + diagonal2);
    let radius = length(vec2f((diagonal1 - diagonal2) / 2.0, offDiagonal));
    let lambda1 = mid + radius;
    let lambda2 = max(mid - radius, 0.1);

    // Use the smaller viewport dimension to limit the kernel size relative to the screen resolution.
    let vmin = min(1024.0, min(uniform.viewport_size.x, uniform.viewport_size.y));

    let l1 = 2.0 * min(sqrt(2.0 * lambda1), vmin);
    let l2 = 2.0 * min(sqrt(2.0 * lambda2), vmin);

    let c = center.proj.ww * uniform.viewport_size.zw;

    // cull against frustum x/y axes
    if (any((abs(center.proj.xy) - vec2f(max(l1, l2)) * c) > center.proj.ww)) {
        return false;
    }

    let diagonalVector = normalize(vec2f(offDiagonal, lambda1 - diagonal1));
    let v1 = l1 * diagonalVector;
    let v2 = l2 * vec2f(diagonalVector.y, -diagonalVector.x);

    corner.offset = vec3f((f32(source.cornerUV.x) * v1 + f32(source.cornerUV.y) * v2) * c, 0.0);
    corner.uv = source.cornerUV;

    return true;
}

#if GSPLAT_2DGS
// 2DGS: Compute oriented quad corner in model space
fn initCorner2DGS(source: ptr<function, SplatSource>, rotation: vec4f, scale: vec3f, corner: ptr<function, SplatCorner>) {
    // Scale by 3.0 for 3-sigma coverage
    let localPos: vec2f = vec2f(source.cornerUV) * vec2f(scale.x, scale.y) * 3.0;

    // Rotate the local position using the quaternion
    let v: vec3f = vec3f(localPos, 0.0);
    let t: vec3f = 2.0 * cross(rotation.xyz, v);
    corner.offset = v + rotation.w * t + cross(rotation.xyz, t);
    corner.uv = source.cornerUV;
}
#endif

// calculate the clip-space offset from the center for this gaussian
fn initCorner(source: ptr<function, SplatSource>, center: ptr<function, SplatCenter>, corner: ptr<function, SplatCorner>) -> bool {
    // Get rotation and scale
    var rotation: vec4f = getRotation().yzwx;  // Convert (w,x,y,z) to (x,y,z,w)
    var scale: vec3f = getScale();

    // Hook: modify rotation and scale
    modifySplatRotationScale(center.modelCenterOriginal, center.modelCenterModified, &rotation, &scale);

    #if GSPLAT_2DGS
        initCorner2DGS(source, rotation, scale, corner);
        return true;
    #else
        // 3DGS: Use covariance-based screen-space projection
        var covA: vec3f;
        var covB: vec3f;
        computeCovariance(half4(rotation.wxyz), half3(scale), &covA, &covB);  // Convert back to (w,x,y,z)

        return initCornerCov(source, center, corner, covA, covB);
    #endif
}
`
);
export {
  gsplatCorner_default as default
};
