var litForwardBackend_default = (
  /* glsl */
  `
void evaluateBackend() {

    // apply SSAO during lighting
    #ifdef LIT_SSAO
        litArgs_ao *= texture2DLod(ssaoTexture, gl_FragCoord.xy * ssaoTextureSizeInv, 0.0).r;
    #endif

    // transform tangent space normals to world space
    #ifdef LIT_NEEDS_NORMAL
        #ifdef LIT_SPECULAR
            getReflDir(litArgs_worldNormal, dViewDirW, litArgs_gloss, dTBN);
        #endif

        #ifdef LIT_CLEARCOAT
            ccReflDirW = normalize(-reflect(dViewDirW, litArgs_clearcoat_worldNormal));
        #endif
    #endif

    #if defined(LIT_SPECULAR_OR_REFLECTION) || defined(LIT_REFRACTION)
        #ifdef LIT_METALNESS
            float f0 = 1.0 / litArgs_ior;
            f0 = (f0 - 1.0) / (f0 + 1.0);
            f0 *= f0;
            #ifdef LIT_SPECULARITY_FACTOR
                litArgs_specularity = getSpecularModulate(litArgs_specularity, litArgs_albedo, litArgs_metalness, f0, litArgs_specularityFactor);
            #else
                litArgs_specularity = getSpecularModulate(litArgs_specularity, litArgs_albedo, litArgs_metalness, f0, 1.0);
            #endif
            litArgs_albedo = getAlbedoModulate(litArgs_albedo, litArgs_metalness);

            // the diffuse transmission is a dielectric lobe, like the diffuse reflection
            #ifdef LIT_DIFFUSE_TRANSMISSION
                litArgs_diffuseTransmission_color = getAlbedoModulate(litArgs_diffuseTransmission_color, litArgs_metalness);
            #endif
        #endif

        #ifdef LIT_IRIDESCENCE
            vec3 iridescenceFresnel = getIridescence(saturate(dot(dViewDirW, litArgs_worldNormal)), litArgs_specularity, litArgs_iridescence_thickness);
        #endif
    #endif

    // ambient
    #ifdef LIT_ADD_AMBIENT

        // the ambient light arriving at the back of the surface, which the diffuse transmission
        // lets through, is added to the diffuse light first and moved out of it
        #ifdef LIT_DIFFUSE_TRANSMISSION
            addAmbient(-litArgs_worldNormal);
            dDiffuseTransmissionLight = dDiffuseLight;
            dDiffuseLight = vec3(0);
        #endif

        addAmbient(litArgs_worldNormal);

        #ifdef LIT_SPECULAR
            dDiffuseLight = dDiffuseLight * (1.0 - litArgs_specularity);

            #ifdef LIT_DIFFUSE_TRANSMISSION
                dDiffuseTransmissionLight *= 1.0 - litArgs_specularity;
            #endif
        #endif

        // move ambient color out of diffuse (used by Lightmapper, to multiply ambient color by accumulated AO)
        #ifdef LIT_SEPARATE_AMBIENT
            vec3 dAmbientLight = dDiffuseLight;
            dDiffuseLight = vec3(0);
        #endif
    #endif

    dDiffuseLight *= litArgs_ambient;

    #ifdef LIT_DIFFUSE_TRANSMISSION
        dDiffuseTransmissionLight *= litArgs_ambient;
    #endif

    // the ambient occlusion darkens the ambient light here, and with occludeDirect, which is 0 or 1,
    // the direct light as well, once that is added below
    #ifdef LIT_AO
        occludeDiffuse(mix(litArgs_ao, 1.0, material_occludeDirect));
    #endif

    #ifdef LIT_LIGHTMAP
        addLightMap(
            litArgs_lightmap, 
            litArgs_lightmapDir, 
            litArgs_worldNormal, 
            dViewDirW, 
            dReflDirW, 
            litArgs_gloss, 
            litArgs_specularity, 
            dVertexNormalW,
            dTBN
        #if defined(LIT_IRIDESCENCE)
            , iridescenceFresnel,
            litArgs_iridescence_intensity
        #endif
        );
    #endif

    #ifdef LIT_LIGHTING || LIT_REFLECTIONS

        #ifdef LIT_REFLECTIONS

            #ifdef LIT_CLEARCOAT
                addReflectionCC(ccReflDirW, litArgs_clearcoat_gloss);
            
                #ifdef LIT_SPECULAR_FRESNEL
                    ccFresnel = getFresnelCC(dot(dViewDirW, litArgs_clearcoat_worldNormal));
                    ccReflection *= ccFresnel;
                #else
                    ccFresnel = 0.0;
                #endif
            #endif

            #ifdef LIT_SPECULARITY_FACTOR
                ccReflection *= litArgs_specularityFactor;
            #endif

            #ifdef LIT_SHEEN
                addReflectionSheen(litArgs_worldNormal, dViewDirW, litArgs_sheen_gloss);
            #endif

            // Fresnel has to be applied to reflections
            addReflection(dReflDirW, litArgs_gloss);

            #ifdef LIT_FRESNEL_MODEL

                dReflection.rgb *= getFresnel(
                    dot(dViewDirW, litArgs_worldNormal), 
                    litArgs_gloss, 
                    litArgs_specularity
                #if defined(LIT_IRIDESCENCE)
                    , iridescenceFresnel,
                    litArgs_iridescence_intensity
                #endif
                    );

            #else

                dReflection.rgb *= litArgs_specularity;

            #endif

        #endif

        #ifdef AREA_LIGHTS
            // specular has to be accumulated differently if we want area lights to look correct
            dSpecularLight *= litArgs_specularity;

            #ifdef LIT_SPECULAR
                // the clear coat reflects the area lights with its own reflectance, as it reflects the
                // other lights and the environment: a dielectric, or no Fresnel without the Fresnel
                // model. Its strength scales all of its light when combined.
                #ifdef LIT_SPECULAR_FRESNEL
                    float ccLTCReflectance = 0.04;
                #else
                    float ccLTCReflectance = 1.0;
                #endif

                // evaluate material based area lights data, shared by all area lights
                calcLTCLightValues(litArgs_gloss, litArgs_worldNormal, dViewDirW, litArgs_specularity, litArgs_clearcoat_gloss, litArgs_clearcoat_worldNormal, ccLTCReflectance);
            #endif
        #endif
        
        // LOOP - evaluate all non-clustered lights
        #ifdef LIGHT_COUNT > 0
            #include "lightEvaluationPS, LIGHT_COUNT"
        #endif

        // clustered lighting
        #ifdef LIT_CLUSTERED_LIGHTS
            addClusteredLights(litArgs_worldNormal, dViewDirW, dReflDirW,
                #if defined(LIT_CLEARCOAT)
                        ccReflDirW,
                #endif
                        litArgs_gloss, litArgs_specularity, dVertexNormalW, dTBN, 
                #if defined(LIT_IRIDESCENCE)
                        iridescenceFresnel,
                #endif
                        litArgs_clearcoat_worldNormal, litArgs_clearcoat_gloss, litArgs_sheen_gloss, litArgs_iridescence_intensity
            );
        #endif

        #ifdef AREA_LIGHTS

            #ifdef LIT_SPECULAR
                litArgs_specularity = vec3(1);
            #endif

        #endif

    #endif

    // the diffuse transmission takes its share of the light entering the surface, and the diffuse
    // reflection the rest
    #ifdef LIT_DIFFUSE_TRANSMISSION
        dDiffuseLight *= 1.0 - litArgs_diffuseTransmission_intensity;
        dDiffuseTransmissionLight *= litArgs_diffuseTransmission_intensity;
    #endif

    // refraction is not gated on lighting / reflections, so that it also works without them
    #ifdef LIT_REFRACTION
        addRefraction(
            litArgs_worldNormal,
            dViewDirW,
            litArgs_thickness,
            litArgs_gloss,
            litArgs_specularity,
            litArgs_albedo,
            litArgs_transmission,
            litArgs_ior,
            litArgs_dispersion
            #if defined(LIT_IRIDESCENCE)
                , iridescenceFresnel,
                litArgs_iridescence_intensity
            #endif
        );

        // refraction replaces the diffuse transmission as it replaces the diffuse reflection
        #ifdef LIT_DIFFUSE_TRANSMISSION
            dDiffuseTransmissionLight *= 1.0 - litArgs_transmission;
        #endif
    #endif

    // apply ambient occlusion
    #ifdef LIT_AO
        occludeDiffuse(mix(1.0, litArgs_ao, material_occludeDirect));

        #if LIT_OCCLUDE_SPECULAR != NONE
            occludeSpecular(litArgs_gloss, litArgs_ao, litArgs_worldNormal, dViewDirW);
        #endif
    #endif

    #if !defined(LIT_OPACITY_FADES_SPECULAR)

        #if LIT_BLEND_TYPE == NORMAL || LIT_BLEND_TYPE == PREMULTIPLIED

            float specLum = dot((dSpecularLight + dReflection.rgb * dReflection.a), vec3( 0.2126, 0.7152, 0.0722 ));
            #ifdef LIT_CLEARCOAT
                specLum += dot(ccSpecularLight * litArgs_clearcoat_specularity + ccReflection * litArgs_clearcoat_specularity, vec3( 0.2126, 0.7152, 0.0722 ));
            #endif
            litArgs_opacity = clamp(litArgs_opacity + gammaCorrectInput(specLum), 0.0, 1.0);

        #endif

        litArgs_opacity *= material_alphaFade;

    #endif

    // end chunks - when baking lightmap
    #ifdef LIT_LIGHTMAP_BAKING
        #ifdef LIT_LIGHTMAP_BAKING_COLOR
            #include "bakeLmEndPS"
        #endif
        #ifdef LIT_LIGHTMAP_BAKING_DIR
            #include "bakeDirLmEndPS"
        #endif
    #else
        // end chunks - in all other cases
        #include "endPS"
        #include "outputAlphaPS"
    #endif

    #ifdef LIT_MSDF
        gl_FragColor = applyMsdf(gl_FragColor);
    #endif

    #include "outputPS"
    #include "debugOutputPS"

    #ifdef LIT_SHADOW_CATCHER
        // output when the shadow catcher is enabled - accumulated shadows
        gl_FragColor.rgb = vec3(dShadowCatcher);
    #endif

    #include "outlineOutputPS"
}
`
);
export {
  litForwardBackend_default as default
};
